"""Extract unmodified IRBI battle narrative banks and explicit event message indices."""
from pathlib import Path
import argparse,importlib.util,json,hashlib
import ndspy.rom,ndspy.narc
p=argparse.ArgumentParser();p.add_argument('rom');p.add_argument('output',type=Path);a=p.parse_args()
spec=importlib.util.spec_from_file_location('events',Path(__file__).with_name('extract-original-events.py'));ev=importlib.util.module_from_spec(spec);spec.loader.exec_module(ev)
r=ndspy.rom.NintendoDSRom.fromFile(a.rom);assert r.idCode==b'IRBI';arc=r.getFileByName('a/0/0/2');f=ndspy.narc.NARC(arc).files
banks={str(i):ev.messages(f[i])for i in[13,14,15]}
assert banks['14'][95]=='La Difesa di {0102:0} nemico diminuisce!'
assert banks['13'][129]=='{0101:0} usa Fulmisguardo!'
triples={'faint':0,'revived':3,'superEffectiveTarget':6,'notVeryEffectiveTarget':15,'failedTarget':24,'immune':210,'miss':213,'unharmed':216,'poison':234,'toxic':237,'poisonDamage':243,'poisonCured':246,'poisonAlready':249,'poisonPrevented':252,'burn':255,'burnDamage':261,'burnCured':264,'burnAlready':267,'burnPrevented':270,'paralysis':273,'paralysisCantMove':276,'paralysisCured':279,'paralysisAlready':282,'paralysisPrevented':285,'freeze':288,'freezeCantMove':291,'freezeCured':294,'freezeAlready':297,'freezePrevented':300,'thawedByMove':303,'sleep':306,'sleepCantMove':309,'sleepCured':312,'sleepAlready':315,'sleepPrevented':318,'nightmareDamage':321,'nightmare':324,'infatuation':327,'infatuationCantMove':336,'infatuationCured':339,'statusCured':342,'confusion':345,'confusionActive':348,'confusionCured':351,'confusionAlready':354,'confusionPrevented':357,'flinch':363,'bindingDamage':372,'bindingEnded':375,'recoil':378,'criticalTarget':384,'heal':387,'ppRestore':390,'allPpRestore':393,'sandDamage':396,'hailDamage':399}
events={k:{'bank':14,'base':v,'sideStride':1}for k,v in triples.items()}
for k,v in {'wildEncounter':1,'sendOut':11,'withdraw':25,'trainerSendOut':17,'trainerWithdraw':31,'trainerSendOutNamedClass':14,'trainerWithdrawNamedClass':30,'winTrainerNamedClass':44,'winTrainer':48,'lose':54,'experience':42,'levelUp':60,'caught':65,'ineffectiveGeneric':68,'failed':71,'escaped':72,'escapeFailed':73,'escapeTrainerForbidden':76,'superEffective':78,'notVeryEffective':79,'confusionSelfHit':80,'critical':81,'noPp':82,'nothingHappened':102}.items():events[k]={'bank':15,'message':v}
order=['atk','def','spa','spd','spe','accuracy','evasion'];statbases={'+1':27,'+2':48,'+3':69,'-1':90,'-2':111,'-3':132,'max':153,'min':174}
stats={key:{stat:{'bank':14,'base':base+i*3,'sideStride':1}for i,stat in enumerate(order)}for key,base in statbases.items()}
data={'source':{'rom':'IRBI','archive':'a/0/0/2','sha256':hashlib.sha256(arc).hexdigest(),'banks':[13,14,15],'method':'Original encrypted message sections decoded; native formatting controls and line breaks retained. Semantic event associations follow unambiguous original text; no changed dialogue.'},'banks':banks,'sides':{'own':0,'wild':1,'trainer':2},'moveUse':{'bank':13,'formula':'3*moveID+side','moveStride':3,'sideStride':1,'maxMoveId':len(banks['13'])//3-1,'patternVerified':True,'note':'Use original complete move-use string; do not reconstruct move names or append generic arrows.'},'events':events,'stats':stats,'statOrder':order,'statNames':{'atk':'Attacco','def':'Difesa','spa':'Attacco Speciale','spd':'Difesa Speciale','spe':'Velocità','accuracy':'precisione','evasion':'elusione'},'font':{'index':0,'atlas':'assets/battle-ui/font-0-message.png','catalog':'assets/battle-ui/provenance.json fonts.0','note':'Existing native message font supports original text. Formatting tokens are not visible glyphs.'},'formatting':{'literalLineBreak':'\\n','tokens':'Preserve raw token type and argument for substitution. {0101:0}/{0102:0}/{010c:0} in the relevant event identify Pokémon; {0107:n} move names, {0109:n} items, {0100:n} trainer names, {010e:n} trainer classes, {020x:n} numbers. Token type is native formatting metadata, not a visible label.','controlTokens':'{be00},{be01},{be09:60},etc control pacing/advancement; do not render literal braces.','statMagnitude':'Choose +1,+2,+3 or -1,-2,-3 based on actual applied stage difference; magnitude>=3 uses the third template family. Max/min have distinct native templates.'}}
a.output.mkdir(parents=True,exist_ok=True)
(a.output/'battle-narrative-assets.js').write_text('window.BATTLE_NARRATIVE='+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf8')
(a.output/'assets/battle-ui/narrative-provenance.json').write_text(json.dumps({k:v for k,v in data.items()if k!='banks'},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print(json.dumps({'banks':{k:len(v)for k,v in banks.items()},'events':len(events),'file':'battle-narrative-assets.js','global':'BATTLE_NARRATIVE'}))
